import{_ as s,o as l,c as n,ah as t}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Bulletins","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/bulletins.md","filePath":"src/guide/admin/bulletins.md"}'),a={name:"guide/admin/bulletins.md"};function i(r,e,o,u,d,c){return l(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="bulletins" tabindex="-1">Bulletins <a class="header-anchor" href="#bulletins" aria-label="Permalink to &quot;Bulletins&quot;">​</a></h1><p>Cette page couvre la publication des bulletins côté administration — une fois que les enseignants ont saisi leurs notes et appréciations pour une période donnée (ce qui est leur propre travail, pas le vôtre), c&#39;est vous qui déclenchez la génération et la mise à disposition des bulletins.</p><h2 id="publier-les-bulletins-d-une-classe" tabindex="-1">Publier les bulletins d&#39;une classe <a class="header-anchor" href="#publier-les-bulletins-d-une-classe" aria-label="Permalink to &quot;Publier les bulletins d&#39;une classe&quot;">​</a></h2><p>Depuis <strong>Paramétrage scolaire → Classes</strong>, cliquez sur <strong>Bulletins</strong> sur la ligne de la classe concernée.</p><p>Pour publier :</p><ol><li>Choisissez la <strong>Période scolaire</strong> concernée dans le menu déroulant en haut de la page.</li><li>Cliquez sur <strong>Publier / republier les bulletins</strong>.</li></ol><p>Cela génère (ou régénère) le bulletin de chaque élève de la classe pour cette période, à partir des notes et appréciations déjà saisies.</p><p>À la <strong>première</strong> publication, les parents de chaque élève reçoivent un e-mail et une notification : c&#39;est par le bulletin qu&#39;ils apprennent les résultats de la période, pas note par note. Republier après une correction met à jour le bulletin déjà publié — les élèves et parents téléchargent toujours la dernière version — sans les prévenir une seconde fois.</p><p>Si aucune période scolaire n&#39;est configurée pour l&#39;année de cette classe, un message vous l&#39;indique — allez d&#39;abord créer une période dans <a href="/era-guide/guide/admin/structure-etablissement.html">Structure de l&#39;établissement</a>.</p><h2 id="suivre-et-telecharger-les-bulletins" tabindex="-1">Suivre et télécharger les bulletins <a class="header-anchor" href="#suivre-et-telecharger-les-bulletins" aria-label="Permalink to &quot;Suivre et télécharger les bulletins&quot;">​</a></h2><p>Le tableau sous le sélecteur de période liste chaque élève de la classe avec :</p><ul><li><strong>Statut</strong> — « Non publié », ou la date de publication du bulletin.</li><li>Un bouton de téléchargement (icône), disponible dès qu&#39;un bulletin a été généré pour cet élève.</li></ul><h2 id="recapitulatifs-de-notes" tabindex="-1">Récapitulatifs de notes <a class="header-anchor" href="#recapitulatifs-de-notes" aria-label="Permalink to &quot;Récapitulatifs de notes {#recapitulatifs-de-notes}&quot;">​</a></h2><p><strong>Enseignement → Récapitulatifs de notes</strong> liste les classes de l&#39;année et, pour chacune, deux portes d&#39;entrée. Le bouton <strong>Récap des notes</strong> de la page des bulletins d&#39;une classe mène au même endroit.</p><ul><li><strong>Récap des notes</strong> — tous les élèves face à toutes les matières, pour la période choisie. Chaque case donne la moyenne de l&#39;élève dans la matière, avec dessous le détail par type d&#39;évaluation (D = devoir, C = composition…). Un point signale une option que l&#39;élève ne suit pas ; une spécialité abandonnée est marquée. La dernière colonne donne la moyenne générale, puis le rang de l&#39;élève dans la classe ; les trois dernières lignes, la moyenne de la classe, la plus basse et la plus haute.</li><li><strong>Une matière</strong> — le relevé de la matière : chaque évaluation de la période, la note de chaque élève telle que saisie (sur le barème de l&#39;évaluation, avec bonus ou malus, absent ou dispensé), puis sa moyenne dans la matière et son rang dans la matière. Seuls les élèves qui suivent la matière y figurent ; les types hors moyenne sont signalés.</li></ul><p>Les moyennes sont <strong>exactement celles des bulletins</strong> : un récapitulatif ne peut pas afficher une autre moyenne que le bulletin du même élève. Deux élèves à la même moyenne (au centième près, telle qu&#39;affichée) partagent le même rang, « 2e ex æquo », et le rang suivant est sauté (1er, 2e, 2e, 4e).</p><p>Chaque écran se télécharge :</p><ul><li>en <strong>PDF</strong>, pour l&#39;imprimer ou le présenter en conseil de classe ;</li><li>en <strong>Excel</strong> (.xlsx), pour le retravailler dans un tableur. Le fichier d&#39;une classe a deux feuilles : le récapitulatif, et les <strong>appréciations du conseil</strong> à remplir.</li></ul><p>L&#39;icône à côté du nom d&#39;un élève, dans le récap de la classe, télécharge son <strong>relevé de notes</strong> en PDF : chacune de ses évaluations, matière par matière, avec ses moyennes et son rang dans la classe.</p><h3 id="importer-depuis-excel" tabindex="-1">Importer des notes et des appréciations depuis Excel <a class="header-anchor" href="#importer-depuis-excel" aria-label="Permalink to &quot;Importer des notes et des appréciations depuis Excel {#importer-depuis-excel}&quot;">​</a></h3><p>Le fichier Excel téléchargé sert aussi de modèle : on le remplit, puis on le renvoie avec le bouton <strong>Importer</strong> du même écran.</p><ul><li><strong>Notes et appréciations d&#39;une matière</strong> — depuis le relevé de la matière. Dans chaque colonne d&#39;évaluation, saisissez la note sur le barème de l&#39;évaluation (12 ou 12,5), « Absent » (ou « abs ») ou « Dispensé » (ou « disp ») ; dans la colonne <strong>Appréciation</strong>, l&#39;appréciation du bulletin. Les évaluations doivent d&#39;abord être créées dans ERA : l&#39;import remplit leurs notes, il n&#39;en crée pas. Un bonus ou un malus déjà donné est conservé. Réservé à l&#39;administration et à l&#39;enseignant de la matière.</li><li><strong>Appréciations du conseil</strong> — depuis le récap de la classe, feuille « Appréciations du conseil » : appréciation générale, conduite, et un « x » pour chaque distinction ou alerte (félicitations, compliments, encouragements, alerte travail, alerte conduite). Réservé à l&#39;administration et au professeur principal.</li></ul><p>Les règles de l&#39;import :</p><ul><li><strong>une case vide ne change rien</strong> à ce qui est déjà dans ERA : on peut réimporter le même fichier après l&#39;avoir complété. Pour les distinctions, sur une ligne remplie, une case vide veut dire « non » ;</li><li><strong>tout ou rien</strong> : le fichier est vérifié en entier avant d&#39;être enregistré. S&#39;il contient une erreur (note hors barème, mot non reconnu, élève inconnu), rien n&#39;est enregistré et chaque ligne à corriger est listée ;</li><li>ne modifiez pas la première colonne (<strong>N° élève</strong>) : c&#39;est elle qui relie chaque ligne à l&#39;élève. Le fichier d&#39;une autre classe, matière ou période est refusé, comme tout import dans une période clôturée ;</li><li>un fichier CSV enregistré depuis Excel est aussi accepté, tant que ses en-têtes de colonnes sont ceux du fichier téléchargé.</li></ul><h2 id="modele-de-bulletin" tabindex="-1">Modèle de bulletin <a class="header-anchor" href="#modele-de-bulletin" aria-label="Permalink to &quot;Modèle de bulletin&quot;">​</a></h2><p>Le modèle visuel utilisé (Classique, Compact ou Traditionnel à la française) se choisit par classe, dans le formulaire de la classe — voir <a href="/era-guide/guide/admin/structure-etablissement.html#classes">Structure de l&#39;établissement</a>. Si aucun modèle n&#39;est choisi pour une classe, le modèle par défaut de l&#39;établissement s&#39;applique.</p><p>Quel que soit le modèle, les matières du bulletin suivent le paramétrage des <a href="/era-guide/guide/admin/structure-etablissement.html#matieres-par-departement">matières par département</a> :</p><ul><li>elles sont regroupées sous leur <strong>rubrique</strong> (« Tronc commun », « Sciences »…), dans l&#39;<strong>ordre</strong> indiqué ; les matières sans rubrique viennent sans intitulé ;</li><li>les <strong>spécialités</strong> forment un bloc à part, « Enseignements de spécialité » : d&#39;abord celles que l&#39;élève suit, puis celles qu&#39;il a abandonnées, marquées « (abandonnée) ».</li></ul><p>Le modèle <strong>Traditionnel</strong> ajoute une colonne par type d&#39;évaluation qui compte dans la moyenne (la moyenne de l&#39;élève en devoirs, en compositions…) et une colonne « Moy. × coef. ». Les types <a href="/era-guide/guide/admin/structure-etablissement.html#types-d-evaluation">hors moyenne</a> n&#39;y figurent pas.</p><p>Un bulletin déjà publié est un document figé : un changement de paramétrage n&#39;apparaît qu&#39;après avoir republié les bulletins de la classe.</p>',30)])])}const g=s(a,[["render",i]]);export{m as __pageData,g as default};
